"""const escapeHtml = value => String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));

// Plain-language reasoning shared by the requirement card and the detail drawer.
function reasoningHtml(r){
  const x=r.explanation;if(!x)return `<p>${escapeHtml(r.whyExists)}</p><p>${escapeHtml(r.whyRanked)}</p>`;
  const parts=r.scoreParts||{},rejected=['not-feasible','pm-rejected'].includes(r.status);
  const segments=[['demand','Customer demand'],['timeline','Timeline fit'],['market','Market evidence'],['memory','Past decisions']].filter(([key])=>parts[key]>0);
  const total=segments.reduce((sum,[key])=>sum+parts[key],0)||1;
  const bullets=items=>`<ul>${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
  return `<div class="why-panel">
    <div class="why-head"><span class="signal signal-${x.signal.tone}"><i aria-hidden="true"></i>${escapeHtml(x.signal.label)}</span>${rejected?'':`<span class="why-score"><strong>${r.score}</strong>/100 priority score</span>`}</div>
    ${x.caveat?`<p class="why-caveat"><strong>Honest caveat</strong>${escapeHtml(x.caveat)}</p>`:''}
    <div class="why-cols"><section><h4>Why it exists</h4>${bullets(x.exists)}</section><section><h4>Why rank #${r.rank}</h4>${bullets(x.rank)}</section></div>
    ${rejected||!segments.length?'':`<div class="score-mix"><h4>What makes up the score</h4><div class="mix-bar" role="img" aria-label="${segments.map(([key,label])=>`${label} ${parts[key]} points`).join(', ')}">${segments.map(([key])=>`<span class="mix-${key}" style="flex:${parts[key]/total}"></span>`).join('')}</div><ul class="mix-legend">${segments.map(([key,label])=>`<li class="mix-${key}"><i aria-hidden="true"></i>${label} <strong>${parts[key]}</strong></li>`).join('')}</ul></div>`}
  </div>`;
}

const SOURCE_GROUPS=[
  ['customer_feedback','What customers said'],['market_study','Customer study'],
  ['competitor','Competitors'],['external_web','Web research'],['sales_volume','Sales planning']
];
const sourceGroupFor=c=>c.sourceType==='customer_feedback'?'customer_feedback':c.sourceType==='market_study'?'market_study':c.sourceType==='sales_volume'?'sales_volume':c.sourceType==='external_web'?'external_web':'competitor';
const friendlyFile=file=>{
  const name=String(file).split('/').pop();
  if(/feedback_hackathon/i.test(name))return `${name.split('_')[0]} customer feedback`;
  if(/customer_studies/i.test(name))return 'Customer studies';
  if(/competitor/i.test(name))return 'Competitor workbook';
  if(/sales_volumes/i.test(name))return 'Sales volumes';
  return name.replace(/\\.[a-z0-9]+$/i,'').replaceAll('_',' ');
};
function citationHtml(c){
  const local=!/^https?:\\/\\//i.test(c.file),external=c.url&&/^https?:\\/\\//i.test(c.url);
  const where=local?`<a href="/sources/${encodeURIComponent(c.file)}" target="_blank" rel="noopener" title="${escapeHtml(`${c.file} › ${c.sheet} › row ${c.row}`)}">${escapeHtml(friendlyFile(c.file))} · row ${escapeHtml(c.row)}</a>`:`<a href="${escapeHtml(c.file)}" target="_blank" rel="noopener">${escapeHtml(new URL(c.file).hostname)}</a>`;
  const text=String(c.excerpt||''),long=text.length>260;
  return `<li class="cite"><blockquote>${long?`<details><summary>${escapeHtml(text.slice(0,240).trimEnd())}… <span>Read full text</span></summary>${escapeHtml(text)}</details>`:escapeHtml(text)}</blockquote><div class="cite-source">${where}${external&&local?`<a class="cite-external" href="${escapeHtml(c.url)}" target="_blank" rel="noopener">Original source ↗</a>`:''}</div></li>`;
}
function citationsHtml(citations){
  return SOURCE_GROUPS.map(([key,label])=>{
    const items=citations.filter(c=>sourceGroupFor(c)===key);if(!items.length)return '';
    const first=items.slice(0,4),rest=items.slice(4);
    return `<section class="cite-group"><h4>${label} <span>${items.length}</span></h4><ul>${first.map(citationHtml).join('')}</ul>${rest.length?`<details class="cite-more"><summary>Show ${rest.length} more</summary><ul>${rest.map(citationHtml).join('')}</ul></details>`:''}</section>`;
  }).join('');
}""")

# Card: honest score + signal, new reasoning panel.
rep("<span>Priority ${r.fitScore} /100</span>","<span>Priority ${r.score}/100</span>${r.explanation?`<span class=\"signal signal-${r.explanation.signal.tone}\"><i aria-hidden=\"true\"></i>${escapeHtml(r.explanation.signal.label)}</span>`:''}")
rep("<div class=\"reasoning-panel\"><section><strong>Customer impact</strong><p>${escapeHtml(r.whyExists)}</p></section><section><strong>Ranking rationale</strong><p>${escapeHtml(r.whyRanked)}</p></section><div class=\"reasoning-tools\">",
    "<div class=\"reasoning-panel\">${reasoningHtml(r)}<div class=\"reasoning-tools\">")

# Drawer: replace the two evidence boxes and flat citation list.
rep("""<div class="evidence-box"><h3>WHY THIS REQUIREMENT EXISTS</h3><p>${escapeHtml(r.problem)}</p><p>${escapeHtml(r.whyExists)}</p><p><strong>Evidence confidence:</strong> ${escapeHtml(r.confidence)} · feedback quality ${Object.entries(r.evidenceQuality).map(([key,value])=>`${key}: ${value}`).join(', ')||'non-feedback evidence only'}</p></div><div class="evidence-box"><h3>WHY THIS REQUIREMENT HAS THIS RANK</h3><p>${escapeHtml(r.whyRanked)}</p></div><h3>Verifiable source evidence</h3>${r.citations.map(c=>`<div class="citation"><a href="/sources/${encodeURIComponent(c.file)}" target="_blank" rel="noopener"><code>${escapeHtml(c.file)} › ${escapeHtml(c.sheet)} › row ${c.row} · ${escapeHtml(c.column)}</code></a>${c.url&&/^https?:\\/\\//i.test(c.url)?`<a class="external-source" href="${escapeHtml(c.url)}" target="_blank" rel="noopener">Open original external source ↗</a>`:''}<p>${escapeHtml(c.excerpt)}</p></div>`).join('')}""",
"""<div class="evidence-box drawer-reasoning">${reasoningHtml(r)}</div><h3 class="sources-title">Sources behind this requirement</h3><p class="sources-help">Every point links to the original workbook row.</p>${citationsHtml(r.citations)}""")
