/* Projector readability and plain-language reasoning. Loaded last. */
:root {
  /* One knob for the whole interface: 1 = original size. */
  --ui-scale: 1.2;
  --signal-strong: #148461;
  --signal-solid: #0669d7;
  --signal-limited: #a35f00;
  --signal-weak: #b42318;
  --mix-demand: #0669d7;
  --mix-timeline: #8fa6bd;
  --mix-market: #172230;
  --mix-memory: #148461;
}

html { zoom: var(--ui-scale); }
/* Zoom scales viewport-sized boxes too; keep the drawer exactly one screen tall. */
dialog {
  height: calc(100dvh / var(--ui-scale)) !important;
  max-height: calc(100dvh / var(--ui-scale)) !important;
}
body { font-size: 15px; }

/* Small utility text was 11–12px; lift it to a readable floor. */
.meta, .meta span, .integrity, .integrity span, .group-button span, .result-count span,
.eyebrow, .section-label, .requirement-label, .outcome, .reasoning-tools button, .evidence-link {
  font-size: 13px !important;
}
.requirement h3 { font-size: 19px !important; line-height: 1.35 !important; }
.group-button strong { font-size: 16px !important; }

/* ---------- Signal chip ---------- */
.signal {
  display: inline-flex; align-items: center; gap: 7px;
  font-weight: 600; white-space: nowrap;
}
.signal i { width: 9px; height: 9px; border-radius: 50%; background: currentColor; flex: none; }
.signal-strong { color: var(--signal-strong); }
.signal-solid { color: var(--signal-solid); }
.signal-limited { color: var(--signal-limited); }
.signal-weak { color: var(--signal-weak); }

/* ---------- Reasoning panel ---------- */
.reasoning-panel { gap: 0 !important; padding: 22px 24px 16px !important; }
.why-panel { display: grid; gap: 18px; color: var(--editorial-ink); }
.why-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.why-head .signal { font-size: 16px; }
.why-score { font-size: 14px; color: var(--editorial-muted); }
.why-score strong { font-size: 24px; font-weight: 700; color: var(--editorial-ink); margin-right: 2px; }

.why-caveat {
  margin: 0 !important; padding: 12px 16px !important;
  background: #fff4f2 !important; border: 1px solid #f3c7c0;
  color: #5c1f17 !important; font-size: 15px !important; line-height: 1.5 !important;
}
.why-caveat strong { display: block; margin-bottom: 3px; color: var(--signal-weak); font-size: 13px; letter-spacing: .06em; text-transform: uppercase; }

.why-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; }
.why-panel h4 {
  margin: 0 0 8px; font-size: 13px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--editorial-muted);
}
.why-panel ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 8px; }
.why-cols li {
  position: relative; padding-left: 18px;
  font-size: 15.5px; line-height: 1.45; color: var(--editorial-ink);
}
.why-cols li::before { content: ''; position: absolute; left: 2px; top: .62em; width: 6px; height: 6px; background: var(--editorial-blue); }

/* Score composition: contributions only, no normalisation maths. */
.mix-bar { display: flex; height: 12px; gap: 2px; background: transparent; }
.mix-bar span { min-width: 4px; }
.mix-demand, .mix-legend .mix-demand i { background: var(--mix-demand); }
.mix-timeline, .mix-legend .mix-timeline i { background: var(--mix-timeline); }
.mix-market, .mix-legend .mix-market i { background: var(--mix-market); }
.mix-memory, .mix-legend .mix-memory i { background: var(--mix-memory); }
.mix-legend { display: flex !important; flex-wrap: wrap; gap: 6px 22px !important; margin-top: 10px !important; }
.mix-legend li { display: inline-flex; align-items: center; gap: 8px; font-size: 14.5px; color: var(--editorial-ink); background: none !important; }
.mix-legend i { width: 12px; height: 12px; flex: none; }
.mix-legend strong { font-variant-numeric: tabular-nums; }

/* ---------- Detail drawer ---------- */
.dialog-body h2 { font-size: 26px !important; line-height: 1.3 !important; }
.drawer-reasoning { padding: 22px !important; }
.drawer-reasoning .why-cols { grid-template-columns: 1fr; gap: 18px; }
.sources-title { margin: 30px 0 4px !important; font-size: 14px !important; }
.sources-help { margin: 0 0 6px; font-size: 14px; color: var(--editorial-muted); }

.cite-group { margin-top: 22px; }
.cite-group h4 {
  display: flex; align-items: center; gap: 10px; margin: 0 0 10px;
  font-size: 16px; font-weight: 700; color: var(--editorial-ink);
}
.cite-group h4 span {
  font-size: 13px; font-weight: 600; color: var(--editorial-muted);
  padding: 1px 8px; border: 1px solid var(--editorial-line);
}
.cite-group ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 10px; }
.cite {
  padding: 14px 16px; background: #fff; border: 1px solid var(--editorial-line);
  border-left: 3px solid var(--editorial-blue);
}
.cite blockquote {
  margin: 0; font-size: 15.5px; line-height: 1.55; color: var(--editorial-ink);
  quotes: '\201C' '\201D';
}
.cite blockquote::before { content: open-quote; }
.cite blockquote::after { content: close-quote; }
.cite blockquote details summary { cursor: pointer; list-style: none; }
.cite blockquote details summary::-webkit-details-marker { display: none; }
.cite blockquote details summary span { color: var(--editorial-blue); font-weight: 600; white-space: nowrap; }
.cite blockquote details[open] summary { display: none; }
.cite-source { display: flex; flex-wrap: wrap; gap: 6px 16px; margin-top: 8px; font-size: 13.5px; }
.cite-source a { color: var(--editorial-muted); text-decoration: underline; text-underline-offset: 3px; }
.cite-source a:hover { color: var(--editorial-blue); }
.cite-source .cite-external { color: var(--editorial-blue); text-decoration: none; }
.cite-more { margin-top: 10px; }
.cite-more summary { cursor: pointer; font-size: 14.5px; font-weight: 600; color: var(--editorial-blue); padding: 6px 0; }
.cite-more ul { margin-top: 10px; }

@media (max-width: 900px) {
  :root { --ui-scale: 1; }
  .why-cols { grid-template-columns: 1fr; }
}

