// Drives the real app in headless Chrome and records the demo walkthrough:
// one 2x screenshot per step plus the on-screen box of the next click (the hotspot).
// Usage: node capture.mjs <base-url> <out-dir> <demo-data-dir>
import { spawn } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const [BASE = 'http://localhost:4175', OUT = '/tmp/walk/shots', DATA] = process.argv.slice(2);
const W = 1440, H = 900, PORT = 9341;
mkdirSync(OUT, { recursive: true });

const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', `--remote-debugging-port=${PORT}`, '--hide-scrollbars', `--user-data-dir=/tmp/walk/profile-${Date.now()}`, 'about:blank']);
const sleep = ms => new Promise(r => setTimeout(r, ms));
for (let i = 0; i < 40; i++) { try { await fetch(`http://127.0.0.1:${PORT}/json`); break; } catch { await sleep(300); } }
const page = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find(t => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl); await new Promise(r => (ws.onopen = r));
let id = 0; const pending = new Map(), errors = [];
ws.onmessage = m => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d.result); pending.delete(d.id); }
  if (d.method === 'Runtime.exceptionThrown') errors.push(d.params.exceptionDetails.exception?.description?.slice(0, 300));
  if (d.method === 'Page.javascriptDialogOpening') send('Page.handleJavaScriptDialog', { accept: true });
};
const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const js = async expression => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(`${expression.slice(0, 120)}\n${r.exceptionDetails.exception?.description}`); return r.result?.value; };
const waitFor = async (expression, timeout = 180000) => { const end = Date.now() + timeout; while (Date.now() < end) { if (await js(expression)) return; await sleep(400); } throw new Error(`Timed out: ${expression}`); };
const rect = selector => js(`(()=>{const el=document.querySelector(${JSON.stringify(selector)});if(!el)return null;const r=el.getBoundingClientRect();return {x:r.x/${W},y:r.y/${H},w:r.width/${W},h:r.height/${H}}})()`);
const click = async selector => {
  const r = await rect(selector); if (!r) throw new Error(`Missing ${selector}`);
  const x = (r.x + r.w / 2) * W, y = (r.y + r.h / 2) * H;
  for (const type of ['mouseMoved', 'mousePressed', 'mouseReleased']) await send('Input.dispatchMouseEvent', { type, x, y, button: 'left', clickCount: 1 });
};
// Scroll so the element's top sits just under the sticky header.
const scrollTo = async (selector, offset = 118) => { await js(`(()=>{const el=document.querySelector(${JSON.stringify(selector)});window.scrollTo(0,window.scrollY+el.getBoundingClientRect().top-${offset})})()`); await sleep(500); };
const setFile = async (selector, file) => { const doc = await send('DOM.getDocument'); const node = await send('DOM.querySelector', { nodeId: doc.root.nodeId, selector }); await send('DOM.setFileInputFiles', { nodeId: node.nodeId, files: [file] }); };
const typeInto = async (selector, text) => { await js(`document.querySelector(${JSON.stringify(selector)}).focus()`); for (const ch of text) await send('Input.insertText', { text: ch }); };

const steps = [];
async function shot(name, target, extra = {}) {
  await sleep(450);
  const hotspot = target ? await rect(target) : null;
  if (target && !hotspot) throw new Error(`Hotspot target missing for ${name}: ${target}`);
  const focus = extra.focus ? await rect(extra.focus) : null;
  const r = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
  writeFileSync(join(OUT, `${name}.png`), Buffer.from(r.data, 'base64'));
  steps.push({ name, hotspot, focus, ...extra.meta });
  console.log(`✓ ${name}${hotspot ? ` hotspot ${Object.values(hotspot).map(v => v.toFixed(3)).join(',')}` : ''}`);
}
const card = match => `[...document.querySelectorAll('.requirement')].find(c=>${match}.test(c.querySelector('h3').textContent+' '+c.querySelector('.outcome').textContent))`;
const markCard = async (match, attr = 'data-demo') => js(`(()=>{document.querySelectorAll('[${attr}]').forEach(e=>e.removeAttribute('${attr}'));const c=${card(match)};if(c)c.setAttribute('${attr}','1');return Boolean(c)})()`);
const ranking = () => js(`[...document.querySelectorAll('.requirement')].map((c,i)=>(i+1)+' '+c.querySelector('.outcome').textContent+' | '+c.querySelector('.meta').textContent.match(/Priority \\d+/)?.[0]).join('\\n')`);

await send('Runtime.enable'); await send('Page.enable'); await send('DOM.enable');
await send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 2, mobile: false });
await send('Page.navigate', { url: BASE });
await waitFor(`document.getElementById('generate-button')&&!document.getElementById('generate-button').disabled`);
await sleep(800);

const SEATS = '/seat/i.test(c.querySelector(".outcome").textContent)&&!/belt/i.test(c.querySelector("h3").textContent)&&/seat/i';
const isSeats = `{test:t=>/seating comfort/i.test(t)&&!/belt/i.test(t)}`;

// ---------- Demo 1 ----------
await js(`document.getElementById('vehicle').value='G60';document.getElementById('vehicle').dispatchEvent(new Event('change'))`);
await js(`document.getElementById('market').value='US';document.getElementById('market').dispatchEvent(new Event('change'))`);
await js(`(()=>{const set=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}))};set('months',18);set('people',12);set('importance',8)})()`);
await scrollTo('#product-context', 105);
await shot('01-setup', '#add-evidence', { meta: { chapter: 'demo1' } });

await click('[data-upload-type="customer_feedback"]');
await click('[data-upload-mode="csv"]');
await setFile('#upload-file', join(DATA, '1-customer-feedback.csv'));
await sleep(400);
await scrollTo('#add-evidence', 105);
await shot('02-evidence', '#upload-preview-button', { meta: { chapter: 'demo1' } });

await click('#upload-preview-button');
await scrollTo('#upload-preview', 110);
await shot('03-preview', '#upload-commit', { meta: { chapter: 'demo1' } });

await click('#upload-commit');
await waitFor(`document.getElementById('upload-errors').classList.contains('success')`);
await scrollTo('.generate-step', 300);
await shot('04-generate', '#generate-button', { meta: { chapter: 'demo1' } });

await click('#generate-button');
await waitFor(`!document.getElementById('workspace').classList.contains('hidden')&&document.querySelectorAll('.requirement').length>0`);
await sleep(1200);
await js(`[...document.querySelectorAll('.group-button')].find(b=>/Interior/.test(b.textContent)).click()`);
await sleep(600);
console.log('Interior ranking, demo 1:\n' + await ranking());
await markCard('/seating comfort/i');
await js(`window.scrollTo(0,0)`); await sleep(300);
await shot('05-requirements', '[data-demo] .card-reasoning summary', { meta: { chapter: 'demo1' } });

await js(`document.querySelector('[data-demo] .card-reasoning').open=true`);
await scrollTo('[data-demo]', 110);
await shot('06-reasoning', '[data-demo] [data-up]', { focus: '[data-demo] .reasoning-panel', meta: { chapter: 'demo1' } });

await click('[data-demo] [data-up]');
await sleep(600);
await markCard('/seating comfort/i');
console.log('After move up:\n' + await ranking());
await js(`document.querySelectorAll('.card-reasoning').forEach(d=>d.open=false)`);
await scrollTo('[data-demo]', 130);
await shot('07-moved', '[data-demo] [data-approve]', { meta: { chapter: 'demo1' } });

await click('[data-demo] [data-approve]');
await waitFor(`document.getElementById('detail-dialog').open`);
await sleep(600);
await typeInto('#pm-rationale', 'Moved seating comfort to #1: seat complaints and defects are a real pain point on long US drives, while the audio settings mostly need clearer controls.');
await js(`document.getElementById('pm-rationale').scrollIntoView({block:'center'})`);
await shot('08-approve', '#approve-requirement', { focus: '#detail-dialog .decision-box', meta: { chapter: 'demo1' } });

await click('#approve-requirement');
await waitFor(`!document.getElementById('detail-dialog').open`);
await sleep(900);
await markCard('/seating comfort/i');
await js(`document.querySelectorAll('.card-reasoning').forEach(d=>d.open=false)`);
await scrollTo('[data-demo]', 130);
await shot('09-approved', null, { meta: { chapter: 'demo1' } });

// ---------- Demo 2: onboarding a new PM ----------
await click('#new-feature-button');
await sleep(900);
await js(`window.scrollTo(0,0)`); await sleep(300);
await shot('10-diary', '#diary-period + .bmw-select .bmw-select-trigger', { meta: { chapter: 'demo2' } });

await scrollTo('.diary-story-controls', 330);
await click('#diary-period + .bmw-select .bmw-select-trigger');
await sleep(500);
const onboardingIndex = await js(`[...document.getElementById('diary-period').options].findIndex(o=>o.value==='onboarding')`);
await shot('11-storyline-menu', `#diary-period + .bmw-select li[data-index="${onboardingIndex}"]`, { meta: { chapter: 'demo2' } });

await click(`#diary-period + .bmw-select li[data-index="${onboardingIndex}"]`);
await sleep(500);
await shot('12-storyline-range', '#diary-story', { meta: { chapter: 'demo2' } });

await click('#diary-story');
await waitFor(`document.querySelector('.diary-summary-card')||document.querySelector('#diary-summary [role=alert]')`, 240000);
await sleep(600);
const storyError = await js(`document.querySelector('#diary-summary [role=alert]')?.textContent||''`);
if (storyError) throw new Error(`Storyline failed: ${storyError}`);
await scrollTo('.diary-summary-card', 120);
await shot('13-storyline', '[data-view="overview"]', { focus: '.diary-summary-card', meta: { chapter: 'demo2' } });

await click('[data-view="overview"]');
await sleep(700);
await js(`(()=>{const set=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}))};set('months',24);set('people',8);set('importance',5)})()`);
await scrollTo('#product-context', 105);
await shot('14-setup-again', '#generate-button', { meta: { chapter: 'demo2' } });

await click('#generate-button');
await sleep(1500);
await waitFor(`!document.getElementById('workspace').classList.contains('hidden')&&!document.getElementById('generate-button').disabled`);
await sleep(1200);
await js(`[...document.querySelectorAll('.group-button')].find(b=>/Interior/.test(b.textContent)).click()`);
await sleep(600);
console.log('Interior ranking, demo 2:\n' + await ranking());
await markCard('/seating comfort/i');
await js(`window.scrollTo(0,0)`); await sleep(300);
await shot('15-requirements-again', '[data-demo] .card-reasoning summary', { meta: { chapter: 'demo2' } });

await js(`document.querySelector('[data-demo] .card-reasoning').open=true`);
await scrollTo('[data-demo]', 110);
